// Generic Result type: Success<T> | Failure<E>
type Result<T, E = Error> =
  | { success: true; data: T }
  | { success: false; error: E };

// Generic API function returning Result<T>
async function fetchAiResponse<T>(url: string): Promise<Result<T>> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      return { success: false, error: new Error(`HTTP ${response.status}: ${response.statusText}`) };
    }
    const data: T = await response.json();
    return { success: true, data };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}

// Usage: TypeScript narrows the type after discriminant check
interface SearchResult { chunks: Array<{ id: string; content: string }>; }

const result = await fetchAiResponse<SearchResult>('/api/search?q=AI+policy');
if (result.success) {
  // result.data is SearchResult - fully typed
  console.log(result.data.chunks.length);
} else {
  // result.error is Error
  console.error(result.error.message);
}

// K extends keyof T: K must be a valid key of T
// Return type T[K]: the exact type of that property
function getProperty<T extends object, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

