// Generic factory with multiple constraints
function createTypedStore<TState extends Record<string, unknown>, TKey extends keyof TState>(
  initialState: TState,
  persistKeys: TKey[]
): { get: <K extends keyof TState>(key: K) => TState[K]; persist: () => Partial<TState> } {
  return {
    get: (key) => initialState[key],
    persist: () => Object.fromEntries(
      persistKeys.map((k) => [k, initialState[k]])
    ) as Partial<TState>,
  };
}

import { useState } from 'react';

// TypeScript infers T from the defaultValue parameter type
function createStoredState<T>(key: string, defaultValue: T) {
  return function useStoredState(): [T, (value: T) => void] {
    const [state, setState] = useState<T>(() => {
      try {
        const stored = localStorage.getItem(key);
        return stored !== null ? (JSON.parse(stored) as T) : defaultValue;
      } catch {
        return defaultValue;
      }
    });

    const setStoredState = (value: T) => {
      setState(value);
      localStorage.setItem(key, JSON.stringify(value));
    };

    return [state, setStoredState];
  };
}

// T inferred as string — no explicit annotation needed
const useSelectedModel = createStoredState('selectedModel', 'gpt-4o');

// T inferred as boolean
const useStreamingEnabled = createStoredState('streamingEnabled', true);

